Here’s a simple, robust way to remove duplicate values from an array in JavaScript:

```js
/**
 * Removes duplicate values from an array.
 * @param {Array} arr - The array to process.
 * @returns {Array} - A new array with duplicates removed.
 */
function removeDuplicates(arr) {
  if (!arr || arr.length === 0) {
    return [];
  }

  // Use a Set to track seen values
  const seen = new Set();

  for (const value of arr) {
    if (!seen.has(value)) {
      seen.add(value);
    }
  }

  return Array.from(seen);
}

// Example usage:
const input = [1, 2, 3, 2, 4, 2, 5, 3, 3, 6];
const result = removeDuplicates(input);
console.log(result); // [1, 2, 3, 4, 5, 6]
```

If you prefer a more concise version using `Set` directly:

```js
function removeDuplicates(arr) {
  return arr.filter((_, index) => !Array.from(arr).some((x, i) => i === index && x === arr[i]));
}
```

Both versions work for arrays of any length.
